"use client";

import { forwardRef, useEffect, useId, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import { AnimatePresence, motion, useAnimate, useReducedMotion } from "motion/react";
import { ArrowRight, Mail } from "lucide-react";
import SegmentedControl from "@/registry/components/segmented-control/segmented-control";
import { motionTokens } from "@/lib/motion-tokens";
import { newsletterCopy, newsletterReaders } from "./newsletter-signup-data";
import styles from "./newsletter-signup.module.css";

export type NewsletterVariant = "inline" | "card";

export interface NewsletterSignupProps {
  /** `inline` puts the copy beside the form in a page section; `card` is a self-contained card with reader faces. */
  variant?: NewsletterVariant;
  title?: string;
  description?: string;
  placeholder?: string;
  buttonLabel?: string;
  /** Short line under the form about frequency and privacy. */
  privacyNote?: ReactNode;
  /** Link after the privacy note. Pass null to hide it. */
  privacyLink?: { label: string; href: string } | null;
  /** Readers for the card variant's social proof. Pass null to hide it. */
  readers?: { count: number; faces: string[] } | null;
  /** Called with a valid, trimmed email. Reject to show an error; resolve to show the success state. */
  onSubscribe?: (email: string) => void | Promise<void>;
  className?: string;
}

type Phase = "idle" | "sending" | "done";
type Bezier = [number, number, number, number];
const enter = [...motionTokens.ease.enter] as Bezier;
const standard = [...motionTokens.ease.standard] as Bezier;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

function validate(value: string) {
  const email = value.trim();
  if (!email) return "Enter your email address";
  if (!EMAIL.test(email)) return "Enter an email like name@company.com";
  return null;
}

const swapIn = { opacity: 0, y: 6, filter: `blur(${motionTokens.blur.subtle}px)` };
const swapShown = { opacity: 1, y: 0, filter: "blur(0px)" };
const swapOut = { opacity: 0, y: -6, filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: .14, ease: standard } };
const fadeIn = { opacity: 0 };
const fadeOut = { opacity: 0, transition: { duration: .1 } };

/** A line that swaps in place: the old text lifts away and the new one rises out of a soft blur. */
function Swap({ id, children, reduced, className, role, live }: { id: string; children: ReactNode; reduced: boolean; className?: string; role?: string; live?: "polite" }) {
  return <div className={className} role={role} aria-live={live}>
    <AnimatePresence initial={false} mode="popLayout">
      <motion.div key={id} initial={reduced ? fadeIn : swapIn} animate={swapShown} exit={reduced ? fadeOut : swapOut} transition={{ duration: reduced ? .12 : .26, ease: enter }}>{children}</motion.div>
    </AnimatePresence>
  </div>;
}

/**
 * A newsletter signup whose email pill validates in place and, on success, morphs its button across the whole field
 * into a confirmation. Comes as an inline page section or a self-contained card.
 */
export const NewsletterSignup = forwardRef<HTMLElement, NewsletterSignupProps>(function NewsletterSignup({
  variant = "inline",
  title,
  description,
  placeholder = "you@company.com",
  buttonLabel = "Subscribe",
  privacyNote = newsletterCopy.privacy,
  privacyLink = newsletterCopy.privacyLink,
  readers = newsletterReaders,
  onSubscribe,
  className,
}, ref) {
  const id = useId();
  const reduced = !!useReducedMotion();
  const [email, setEmail] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [tried, setTried] = useState(false);
  const [phase, setPhase] = useState<Phase>("idle");
  const [sentTo, setSentTo] = useState("");
  const input = useRef<HTMLInputElement>(null);
  const again = useRef<HTMLButtonElement>(null);
  const refocus = useRef(false);
  const [pill, animatePill] = useAnimate<HTMLDivElement>();
  const copy = newsletterCopy[variant];

  useEffect(() => {
    if (phase === "idle" && refocus.current) { refocus.current = false; input.current?.focus(); }
    if (phase === "done") again.current?.focus();
  }, [phase]);

  function shake() {
    if (reduced || !pill.current) return;
    animatePill(pill.current, { x: [0, -7, 6, -4, 2, 0] }, { duration: .38, ease: "easeOut" });
  }

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (phase !== "idle") return;
    setTried(true);
    const found = validate(email);
    setError(found);
    if (found) { shake(); input.current?.focus(); return; }
    const value = email.trim();
    setPhase("sending");
    try {
      await (onSubscribe ? onSubscribe(value) : new Promise(resolve => setTimeout(resolve, 900)));
      setSentTo(value);
      setPhase("done");
    } catch {
      setPhase("idle");
      setError("We couldn't subscribe you. Check your connection and try again.");
      shake();
    }
  }

  function reset() {
    setEmail("");
    setError(null);
    setTried(false);
    refocus.current = true;
    setPhase("idle");
  }

  const done = phase === "done";
  const messageId = `${id}-message`;
  const morph = reduced ? { duration: 0 } : motionTokens.spring.morph;

  const form = <form className={styles.form} onSubmit={submit} noValidate aria-label={title ?? copy.title}>
    <motion.div ref={pill} className={styles.pill} data-invalid={error ? "" : undefined} data-done={done ? "" : undefined} style={{ borderRadius: 999 }}>
      <AnimatePresence initial={false} mode="popLayout">
        {!done && <motion.div key="field" className={styles.field} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, filter: reduced ? "none" : `blur(${motionTokens.blur.subtle}px)`, transition: { duration: .14 } }}>
          <Mail className={styles.mailIcon} size={16} strokeWidth={1.75} aria-hidden="true" />
          <label htmlFor={`${id}-email`} className={styles.srOnly}>Email address</label>
          <input
            ref={input}
            id={`${id}-email`}
            className={styles.input}
            type="email"
            name="email"
            inputMode="email"
            autoComplete="email"
            placeholder={placeholder}
            value={email}
            readOnly={phase === "sending"}
            aria-invalid={error ? true : undefined}
            aria-describedby={messageId}
            onChange={event => { setEmail(event.target.value); if (tried) setError(validate(event.target.value)); }}
          />
        </motion.div>}
      </AnimatePresence>
      <motion.button
        layout={!reduced}
        transition={morph}
        type={done ? "button" : "submit"}
        className={styles.submit}
        data-done={done ? "" : undefined}
        aria-busy={phase === "sending" || undefined}
        aria-disabled={done || undefined}
        tabIndex={done ? -1 : undefined}
        style={{ borderRadius: 999 }}
        whileTap={reduced || done ? undefined : { scale: .97 }}
      >
        <motion.span layout={reduced ? false : "position"} transition={morph} className={styles.submitInner}>
          <AnimatePresence initial={false} mode="popLayout">
            <motion.span key={phase} className={styles.submitLabel} initial={reduced ? fadeIn : swapIn} animate={swapShown} exit={reduced ? fadeOut : swapOut} transition={{ duration: reduced ? .12 : .24, ease: enter }}>
              {phase === "idle" && <>{buttonLabel}<ArrowRight size={15} strokeWidth={2} aria-hidden="true" /></>}
              {phase === "sending" && <><span className={styles.spinner} aria-hidden="true" />Subscribing</>}
              {done && <><span className={styles.check} aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><motion.path d="M5 12.5l4.5 4.5L19 7.5" initial={reduced ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduced ? 0 : .38, ease: enter, delay: .18 }} /></svg></span>You&rsquo;re subscribed</>}
            </motion.span>
          </AnimatePresence>
        </motion.span>
      </motion.button>
    </motion.div>
    <Swap id={error ? `error-${error}` : done ? "done" : "note"} reduced={reduced} className={styles.message} live="polite">
      <p id={messageId} className={styles.note} data-tone={error ? "error" : done ? "success" : undefined} role={error ? "alert" : undefined}>
        {error ?? (done
          ? <>Check {sentTo} for a confirmation link. <button ref={again} type="button" className={styles.textButton} onClick={reset}>Use a different email</button></>
          : <>{privacyNote}{privacyLink && <> <a className={styles.link} href={privacyLink.href}>{privacyLink.label}</a></>}</>)}
      </p>
    </Swap>
  </form>;

  if (variant === "card") {
    const count = readers ? new Intl.NumberFormat("en-US").format(readers.count) : "";
    return <section ref={ref} className={[styles.newsletter, className].filter(Boolean).join(" ")} data-variant="card" aria-labelledby={`${id}-title`}>
      <div className={styles.card}>
        {readers && <div className={styles.readers}>
          <span className={styles.faces} aria-hidden="true">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            {readers.faces.slice(0, 3).map(src => <img key={src} src={src} alt="" width={24} height={24} />)}
          </span>
          <Swap id={done ? "you" : "join"} reduced={reduced} className={styles.readerLine}>
            <span>{done ? `You and ${count} others` : `Join ${count} readers`}</span>
          </Swap>
        </div>}
        <h2 id={`${id}-title`} className={styles.cardTitle}>{title ?? copy.title}</h2>
        <p className={styles.description}>{description ?? copy.description}</p>
        {form}
      </div>
    </section>;
  }

  return <section ref={ref} className={[styles.newsletter, className].filter(Boolean).join(" ")} data-variant="inline" aria-labelledby={`${id}-title`}>
    <div className={styles.inline}>
      <div className={styles.intro}>
        <h2 id={`${id}-title`} className={styles.title}>{title ?? copy.title}</h2>
        <p className={styles.description}>{description ?? copy.description}</p>
      </div>
      {form}
    </div>
  </section>;
});

NewsletterSignup.displayName = "NewsletterSignup";

const variantOptions = [{ value: "inline", label: "Inline" }, { value: "card", label: "Card" }];

/** Preview: both layouts. Subscribing is simulated and nothing is sent. */
export function NewsletterSignupBlock() {
  const [variant, setVariant] = useState<NewsletterVariant>("inline");
  return <div className={styles.preview}>
    <SegmentedControl label="Newsletter layout" options={variantOptions} value={variant} onValueChange={next => setVariant(next as NewsletterVariant)} />
    <div className={styles.frame}>
      <NewsletterSignup key={variant} variant={variant} />
    </div>
  </div>;
}

export default NewsletterSignupBlock;

.newsletter { container: newsletter / inline-size; background: var(--background); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.newsletter *, .newsletter *::before, .newsletter *::after { box-sizing: border-box; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Inline: copy beside the form in a page section. */
.inline { display: grid; max-width: 1120px; grid-template-columns: minmax(0, 1fr) minmax(0, 460px); align-items: center; gap: var(--space-8) var(--space-16); margin: 0 auto; padding: var(--space-20) var(--space-8); }
.intro { display: grid; gap: var(--space-3); max-width: 520px; }
.title { margin: 0; font-family: var(--font-display); font-size: clamp(1.75rem, 1rem + 2.4cqi, var(--text-3xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.description { margin: 0; color: var(--text-secondary); font-size: var(--text-base); line-height: 1.5; text-wrap: pretty; }

/* Card: a self-contained card centered in its section. */
.newsletter[data-variant="card"] { display: grid; place-items: center; padding: var(--space-20) var(--space-6); }
.card { display: grid; width: min(100%, 480px); gap: var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-surface); padding: var(--space-8); background: var(--surface); box-shadow: var(--shadow-resting); }
.cardTitle { margin: var(--space-2) 0 0; font-family: var(--font-display); font-size: var(--text-2xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.card .description { margin-bottom: var(--space-3); font-size: var(--text-sm); }
.readers { display: flex; align-items: center; gap: var(--space-3); color: var(--text-secondary); font-size: var(--text-sm); }
.faces { display: flex; padding-left: 6px; }
.faces img { display: block; width: 26px; height: 26px; margin-left: -6px; border: 2px solid var(--surface); border-radius: 50%; object-fit: cover; }
.readerLine { position: relative; min-width: 0; }

/* The pill: one field that holds the input and the button, and becomes the confirmation. */
.form { display: grid; gap: var(--space-3); min-width: 0; }
.pill { position: relative; display: flex; height: 52px; align-items: center; gap: 4px; border: 1px solid var(--border); padding: 5px; background: var(--surface); transition: border-color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-fast) var(--ease-standard); }
.pill:hover { border-color: var(--border-strong); }
.pill:focus-within { border-color: var(--border-strong); box-shadow: var(--shadow-resting); }
.pill[data-invalid] { border-color: color-mix(in oklch, var(--danger) 55%, var(--border)); }
.pill[data-done] { border-color: color-mix(in oklch, var(--success) 30%, var(--border)); }
.field { display: flex; min-width: 0; height: 100%; flex: 1; align-items: center; gap: 10px; padding-left: 12px; }
.mailIcon { flex: none; color: var(--text-muted); }
.input { width: 100%; min-width: 0; height: 100%; border: 0; padding: 0; background: none; color: var(--foreground); font: inherit; font-size: var(--text-base); letter-spacing: inherit; outline: none; }
.input::placeholder { color: var(--text-muted); }

.submit { position: relative; display: inline-flex; height: 100%; flex: none; align-items: center; justify-content: center; border: 0; padding: 0 18px; background: var(--foreground); color: var(--background); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; white-space: nowrap; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .submit:not([data-done]):hover { background: color-mix(in oklch, var(--foreground) 86%, var(--background)); } }
.submit[data-done] { flex: 1; background: color-mix(in oklch, var(--success) 12%, var(--surface)); color: var(--success); cursor: default; }
.submitInner { display: inline-grid; }
.submitLabel { display: inline-flex; grid-area: 1 / 1; align-items: center; gap: 8px; }
.spinner { width: 14px; height: 14px; border: 2px solid color-mix(in oklch, currentColor 30%, transparent); border-top-color: currentColor; border-radius: 50%; animation: spin 700ms linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.check { display: inline-flex; }
.check svg { width: 17px; height: 17px; }

.message { position: relative; min-height: 20px; }
.note { margin: 0; padding-left: 4px; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); text-wrap: pretty; }
.note[data-tone="error"] { color: var(--danger); }
.note[data-tone="success"] { color: var(--text-secondary); }
.link, .textButton { color: var(--foreground); text-decoration: underline; text-decoration-color: var(--border-strong); text-underline-offset: 3px; transition: text-decoration-color var(--duration-fast) var(--ease-standard); }
.textButton { border: 0; padding: 0; background: none; font: inherit; cursor: pointer; }
@media (hover: hover) and (pointer: fine) { .link:hover, .textButton:hover { text-decoration-color: currentColor; } }

@container newsletter (max-width: 820px) {
  .inline { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
}
@container newsletter (max-width: 520px) {
  .inline { padding: var(--space-12) var(--space-4); }
  .newsletter[data-variant="card"] { padding: var(--space-10) var(--space-4); }
  .card { padding: var(--space-6); border-radius: 28px; }
}
@container newsletter (max-width: 380px) {
  .pill { height: auto; flex-direction: column; align-items: stretch; border-radius: 22px !important; }
  .field { height: 44px; }
  .submit { height: 44px; border-radius: 18px !important; }
  .submit[data-done] { height: 44px; }
}

.preview { display: grid; width: 100%; justify-items: center; gap: var(--space-4); }
.frame { width: 100%; overflow: hidden; border: 1px solid var(--border); border-radius: 20px; background: var(--background); }

@media (prefers-reduced-motion: reduce) {
  .pill, .submit { transition: none; }
  .spinner { animation-duration: 1.6s; }
}

